        var seen = Set<String>()
        var order: [String] = []
        for key in Self.orderedKeys(describeJSON: describeJSON)
        where schema[key] != nil && !seen.contains(key) {
            seen.insert(key)
            order.append(key)
        }
        order += schema.keys.filter { !seen.contains($0) }.sorted()
        entries = order.map { key in
            let entry = schema[key] as? [String: Any] ?? [:]
